#!/usr/bin/env python3
"""Validate that report_cover.pdf has a dated 'Annual Financial Report' cover."""
import sys
from datetime import date

from pypdf import PdfReader


def main() -> int:
    input_pdf, output_pdf = "report.pdf", "report_cover.pdf"
    errors = []

    try:
        report = PdfReader(input_pdf)
    except Exception as exc:
        print(f"error: cannot read {input_pdf}: {exc}")
        return 1

    try:
        cover = PdfReader(output_pdf)
    except Exception as exc:
        print(f"error: cannot read {output_pdf}: {exc}")
        return 1

    n_report = len(report.pages)
    n_cover = len(cover.pages)
    print(f"{input_pdf}: {n_report} pages")
    print(f"{output_pdf}: {n_cover} pages")

    if n_report == 0:
        errors.append("input PDF is empty")
    if n_cover != n_report + 1:
        errors.append(f"expected {n_report + 1} pages, found {n_cover}")

    today = date.today().strftime("%B %d, %Y")
    cover_text = (cover.pages[0].extract_text() or "").replace("\n", " ")
    print(f"cover text: {cover_text[:200]!r}")

    if "Annual Financial Report" not in cover_text:
        errors.append("cover title 'Annual Financial Report' missing")
    if today not in cover_text:
        errors.append(f"cover date '{today}' missing")

    # Sanity: original first page still present as page 2
    if n_cover >= 2 and n_report >= 1:
        p2 = (cover.pages[1].extract_text() or "").strip()
        p1 = (report.pages[0].extract_text() or "").strip()
        if not p2 or p2 != p1:
            errors.append("page 2 of output does not match original page 1")

    if errors:
        for e in errors:
            print(f"FAIL: {e}")
        return 1

    print(f"PASS: {output_pdf} has a cover titled 'Annual Financial Report' dated {today}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

